package glitch

import data.glitch_lib

# CWE-353: Missing Support for Integrity Check
# Detect insecure protocol configurations and missing integrity checks

# Set of insecure protocols that lack integrity checks
insecure_protocols := {"http", "ftp", "telnet", "ftp:", "http:"}

# Check for insecure protocol in string values
check_insecure_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)^(http|ftp|telnet)://", value.value)
} else {
    value.ir_type == "String"
    insecure_protocols[value.value]
} else {
    value.ir_type == "Sum"
    check_insecure_protocol(value.left)
} else {
    value.ir_type == "Sum"
    check_insecure_protocol(value.right)
}

# Check for disabled TLS/SSL
check_tls_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    regex.match("(?i)(disabled|none|false)", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check for missing integrity check attributes
check_missing_integrity(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check attributes for insecure protocol configuration
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for insecure protocol in attributes
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check protocol attribute
    attr.name == "protocol"
    check_insecure_protocol(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Insecure protocol configuration detected (CWE-353)"
    }
}

# Check for disabled TLS/SSL
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for TLS/SSL disabled attributes
    (attr.name == "tls_disabled" || attr.name == "ssl_disabled" || attr.name == "enable_tls" || attr.name == "ssl_mode")
    check_tls_disabled(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - TLS/SSL disabled (CWE-353)"
    }
}

# Check for missing integrity check flags
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for integrity check attributes
    (attr.name == "gpgcheck" || attr.name == "validate_checksum" || attr.name == "integrity_check")
    check_missing_integrity(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Integrity validation disabled (CWE-353)"
    }
}

# Check for insecure URLs in source/download attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check source/url attributes for insecure protocols
    (attr.name == "source" || attr.name == "url" || attr.name == "baseurl")
    check_insecure_protocol(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Insecure source URL detected (CWE-353)"
    }
}

